// The app's single chat connection. It runs the IRC client package on a socket
// from the fake IRC server (benchmark mode) or a real WebSocket, and converts
// the client's events into ChatEvents for the message buffers.
import { createClient, codePointLength } from "twitch-irc";
import type {
  Client,
  ChatEventData,
  ClearChatEventData,
  ClearMsgEventData,
  IrcChatMessage,
  IrcEmote,
  IrcFlag,
  IrcUser,
  RoomStateEventData,
  UserNoticeEventData,
  NoticeEventData,
  HostTargetEventData,
} from "twitch-irc";
import * as timers from "../platform/timers";
import { openIrcSocket } from "../platform/fake-irc";
import { benchmarkMode } from "../workload/benchmark";
import type { ChatConnectionAPI } from "./buffer-api";
import { tokenize, mentionsUser } from "./tokenizer";
import {
  ChatEventType,
  type AutoModFlag,
  type BadgeRef,
  type ChatEvent,
  type ChatMessageEvent,
  type ChatNoticeEvent,
  type ChatUser,
  type EmoteRange,
  type ReplyInfo,
} from "./types";

const FALLBACK_COLORS = [
  "#FF0000",
  "#0000FF",
  "#008000",
  "#B22222",
  "#FF7F50",
  "#9ACD32",
  "#FF4500",
  "#2E8B57",
  "#DAA520",
  "#D2691E",
  "#5F9EA0",
  "#1E90FF",
  "#FF69B4",
  "#8A2BE2",
  "#00FF7F",
];

const colorCache = new Map<string, string>();

/** A stable pick from the palette per user id: FNV-1a over the id's characters. */
function fallbackColor(userID: string): string {
  let color = colorCache.get(userID);
  if (color === undefined) {
    let hash = 0x811c9dc5;
    for (let i = 0; i < userID.length; i++) {
      hash ^= userID.charCodeAt(i);
      hash = Math.imul(hash, 0x01000193);
    }
    color = FALLBACK_COLORS[(hash >>> 0) % FALLBACK_COLORS.length];
    colorCache.set(userID, color);
  }
  return color;
}

function isInternational(displayName: string): boolean {
  return displayName
    .split("")
    .map((c) => c.charCodeAt(0) > 127)
    .reduce((any, wide) => any || wide, false);
}

function convertUser(user: IrcUser): ChatUser {
  const badges: BadgeRef[] = Object.keys(user.badges).map((setID) => ({ setID, version: user.badges[setID] }));
  return {
    userID: user.id,
    userLogin: user.login,
    displayName: user.displayName,
    color: user.color || fallbackColor(user.id || user.login),
    isIntl: isInternational(user.displayName),
    userType: user.userType,
    isSubscriber: user.subscriber,
    isMod: user.mod,
    isVip: user.vip,
    isTurbo: user.turbo,
    isReturningChatter: user.returningChatter,
    badges,
    badgeDynamicData: user.badgeInfo,
  };
}

function convertReply(message: IrcChatMessage): ReplyInfo | null {
  const reply = message.reply;
  return reply && { ...reply };
}

/**
 * A reply's body starts with "@parent ". It is dropped from the body, and the
 * emote and flag ranges, which count code points of the full body, move left.
 */
function stripReplyPrefix(message: IrcChatMessage): {
  body: string;
  emotes: Record<number, EmoteRange>;
  flags: AutoModFlag[];
} {
  const prefix = message.reply ? `@${message.reply.parentDisplayName} ` : "";
  if (!prefix || !message.body.startsWith(prefix)) {
    return { body: message.body, emotes: message.emotes as Record<number, EmoteRange>, flags: message.flags as AutoModFlag[] };
  }
  const shift = codePointLength(prefix);
  const emotes: Record<number, EmoteRange> = {};
  for (const emote of Object.values(message.emotes) as IrcEmote[]) {
    if (emote.startIndex < shift) continue;
    emotes[emote.startIndex - shift] = { startIndex: emote.startIndex - shift, endIndex: emote.endIndex - shift, id: emote.id };
  }
  const flags: AutoModFlag[] = [];
  for (const flag of message.flags as IrcFlag[]) {
    if (flag.endIndex < shift) continue;
    flags.push({ startIndex: Math.max(0, flag.startIndex - shift), endIndex: flag.endIndex - shift, categories: flag.categories });
  }
  return { body: message.body.slice(prefix.length), emotes, flags };
}

function buildMessage(message: IrcChatMessage): ChatMessageEvent {
  const { body, emotes, flags } = stripReplyPrefix(message);
  const messageParts = tokenize({ body, emotes, flags, bits: message.bits });
  const mentioning = mentionsUser(messageParts);
  return {
    type: message.isAction ? ChatEventType.Action : ChatEventType.Message,
    id: message.id ?? uniqueId("message"),
    channel: message.channel,
    roomID: message.roomId,
    timestamp: message.timestamp,
    user: convertUser(message.user),
    body,
    messageParts,
    emotes,
    flags,
    bits: message.bits,
    reply: convertReply(message),
    isFirstMsg: message.firstMsg,
    msgId: message.msgId,
    nonce: message.nonce,
    deleted: false,
    banned: false,
    isHistorical: false,
    isHighlighted: message.msgId === "highlighted-message",
    isMentioningCurrentUser: mentioning,
  };
}

let idCounter = 0;
function uniqueId(prefix: string): string {
  return `${prefix}-${++idCounter}`;
}

const USERNOTICE_TYPES: Record<string, ChatEventType> = {
  subscription: ChatEventType.Subscription,
  resubscription: ChatEventType.Resubscription,
  subgift: ChatEventType.SubGift,
  submysterygift: ChatEventType.SubMysteryGift,
  giftpaidupgrade: ChatEventType.GiftPaidUpgrade,
  raid: ChatEventType.Raid,
  announcement: ChatEventType.Announcement,
  bitsbadgetier: ChatEventType.BitsBadgeTier,
  ritual: ChatEventType.Ritual,
};

function notice(type: ChatEventType, channel: string, systemMessage: string, timestamp: number, params: Record<string, string> = {}): ChatNoticeEvent {
  return {
    type: type as ChatNoticeEvent["type"],
    id: uniqueId(type),
    channel,
    timestamp,
    msgId: null,
    systemMessage,
    user: null,
    body: null,
    messageParts: null,
    params,
  };
}

function buildUserNotice(data: UserNoticeEventData): ChatNoticeEvent {
  const event = notice(USERNOTICE_TYPES[data.type] ?? ChatEventType.Notice, data.channel, data.systemMessage, data.timestamp, data.params);
  event.id = data.id ?? event.id;
  event.msgId = data.msgId;
  event.user = convertUser(data.user);
  if (data.message) {
    const built = buildMessage(data.message);
    event.body = built.body;
    event.messageParts = built.messageParts;
  }
  return event;
}

function describeModeration(data: ClearChatEventData): string {
  if (data.duration === null) return `${data.target} was permanently banned.`;
  return `${data.target} was timed out for ${data.duration} seconds.`;
}

const MODE_EVENTS: Array<[keyof RoomStateEventData["changes"], ChatEventType]> = [
  ["slow", ChatEventType.SlowMode],
  ["subsOnly", ChatEventType.SubsOnlyMode],
  ["followersOnly", ChatEventType.FollowersOnlyMode],
  ["emoteOnly", ChatEventType.EmoteOnlyMode],
  ["r9k", ChatEventType.R9KMode],
];

type Handler = (event: ChatEvent) => void;

export class ChatConnection implements ChatConnectionAPI {
  private readonly client: Client;
  private readonly handlers = new Map<string, Handler>();

  constructor() {
    this.client = createClient({
      createSocket: (url) => openIrcSocket(url, benchmarkMode),
      timers,
      random: () => 0.5,
    });
    this.client.on("chat", (data) => this.onChat(data));
    this.client.on("usernotice", (data) => this.dispatch(data.channel, buildUserNotice(data)));
    this.client.on("clearchat", (data) => this.onClearChat(data));
    this.client.on("clearmsg", (data) => this.onClearMsg(data));
    this.client.on("roomstate", (data) => this.onRoomState(data));
    this.client.on("notice", (data) => this.onNotice(data));
    this.client.on("hosttarget", (data) => this.onHostTarget(data));
    this.client.on("join", (data) => {
      if (data.isSelf) this.dispatch(data.channel, notice(ChatEventType.Welcome, data.channel, "Welcome to the chat room!", data.timestamp));
    });
    this.client.on("reconnect", () => this.dispatchAll(ChatEventType.Reconnect, "Reconnecting to chat..."));
    this.client.on("disconnected", () => this.dispatchAll(ChatEventType.Disconnected, "Disconnected from chat."));
  }

  join(login: string, onEvent: Handler): void {
    this.handlers.set(login, onEvent);
    this.client.join(login);
    this.client.connect();
  }

  part(login: string): void {
    this.handlers.delete(login);
    this.client.part(login);
  }

  isConnected(): boolean {
    return this.client.isRegistered;
  }

  private dispatch(channel: string | null, event: ChatEvent): void {
    if (channel === null) return;
    this.handlers.get(channel)?.(event);
  }

  private dispatchAll(type: ChatEventType, text: string): void {
    for (const channel of this.handlers.keys()) this.dispatch(channel, notice(type, channel, text, timers.now()));
  }

  private onChat(data: ChatEventData): void {
    this.dispatch(data.channel, buildMessage(data.message));
  }

  private onClearChat(data: ClearChatEventData): void {
    if (!data.target) {
      this.dispatch(data.channel, notice(ChatEventType.ChatCleared, data.channel, "Chat was cleared by a moderator.", data.timestamp));
      return;
    }
    const action = data.duration === null ? "ban" : "timeout";
    const event = notice(ChatEventType.Moderation, data.channel, describeModeration(data), data.timestamp, {
      action,
      login: data.target,
      targetUserId: data.targetUserId ?? "",
      duration: String(data.duration ?? 0),
    });
    this.dispatch(data.channel, event);
  }

  private onClearMsg(data: ClearMsgEventData): void {
    const event = notice(ChatEventType.Moderation, data.channel, `A message from ${data.login} was deleted.`, data.timestamp, {
      action: "delete",
      login: data.login,
      targetMsgId: data.targetMsgId,
    });
    this.dispatch(data.channel, event);
  }

  private onRoomState(data: RoomStateEventData): void {
    if (data.initial) return;
    for (const [key, type] of MODE_EVENTS) {
      if (data.changes[key] === undefined) continue;
      this.dispatch(data.channel, notice(type, data.channel, `Chat mode ${key} is now ${String(data.changes[key])}.`, data.timestamp, { value: String(data.changes[key]) }));
    }
  }

  private onNotice(data: NoticeEventData): void {
    const event = notice(ChatEventType.Notice, data.channel ?? "", data.body, data.timestamp);
    event.msgId = data.msgId;
    if (data.channel) this.dispatch(data.channel, event);
    else this.dispatchAllEvent(event);
  }

  private dispatchAllEvent(event: ChatNoticeEvent): void {
    for (const channel of this.handlers.keys()) this.dispatch(channel, { ...event, channel });
  }

  private onHostTarget(data: HostTargetEventData): void {
    const text = data.target ? `Now hosting ${data.target} for ${data.viewers} viewers.` : "Exited host mode.";
    this.dispatch(data.channel, notice(ChatEventType.Notice, data.channel, text, data.timestamp, { target: data.target ?? "" }));
  }
}

let connection: ChatConnection | null = null;

/** The app's shared chat connection, created on first use. */
export function getChatConnection(): ChatConnection {
  return (connection ??= new ChatConnection());
}
