import { forwardRef, type ButtonHTMLAttributes, type ElementType, type ReactNode } from "react";
import styled, { css } from "styled-components";
import { SvgIcon, type IconName } from "./svg";

export type ButtonVariant = "primary" | "secondary" | "text" | "icon";
export type ButtonSize = "small" | "default" | "large";

interface ButtonStyleProps {
  $variant: ButtonVariant;
  $size: ButtonSize;
  $overlay?: boolean;
  $fullWidth?: boolean;
  $active?: boolean;
}

const heights = { small: "2.4rem", default: "3.0rem", large: "4.0rem" } as const;

export const ScCoreButton = styled.button.attrs({ className: "tw-core-button" })<ButtonStyleProps>`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: relative;
  border: 0;
  cursor: pointer;
  user-select: none;
  white-space: nowrap;
  text-decoration: none;
  font-weight: 600;
  height: ${({ $size }) => heights[$size]};
  border-radius: ${({ theme }) => theme.radii.medium};
  ${({ $fullWidth }) => $fullWidth && "width: 100%;"}
  ${({ theme, $variant, $overlay, $active }) => {
    switch ($variant) {
      case "primary":
        return css`
          padding: 0 1rem;
          color: #fff;
          background: ${theme.colors.brand};
          &:hover { background: ${theme.colors.brandHover}; }
        `;
      case "secondary":
        return css`
          padding: 0 1rem;
          color: ${theme.colors.text};
          background: ${theme.colors.hoverBg};
          &:hover { background: ${theme.colors.border}; }
        `;
      case "icon":
        return css`
          width: ${heights.default};
          padding: 0;
          color: ${$active ? theme.colors.brand : theme.colors.textAlt};
          background: transparent;
          &:hover { background: ${theme.colors.hoverBg}; color: ${theme.colors.text}; }
        `;
      default:
        return css`
          padding: 0 0.8rem;
          color: ${$overlay ? "#efeff1" : theme.colors.text};
          background: transparent;
          &:hover { background: ${$overlay ? "rgba(255,255,255,0.2)" : theme.colors.hoverBg}; }
        `;
    }
  }}
  &:focus-visible {
    outline: 2px solid ${({ theme }) => theme.colors.brand};
  }
  &:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
`;

interface CoreInteractiveProps {
  as?: ElementType;
  children?: ReactNode;
  [prop: string]: unknown;
}

/** The interactive-element layer under buttons: renders the element or styled component given by `as`. */
export const CoreInteractive = forwardRef<HTMLElement, CoreInteractiveProps>(function CoreInteractive(
  { as = "button", children, ...rest },
  ref,
) {
  const Tag = as as ElementType;
  return (
    <Tag ref={ref} {...rest}>
      {children}
    </Tag>
  );
});

export interface CoreButtonProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  overlay?: boolean;
  fullWidth?: boolean;
  active?: boolean;
  children?: ReactNode;
}

/** A button with design-system variants; the ScCoreButton styled button does the styling. */
export const CoreButton = forwardRef<HTMLButtonElement, CoreButtonProps>(function CoreButton(
  { variant = "primary", size = "default", overlay, fullWidth, active, children, type = "button", ...rest },
  ref,
) {
  return (
    <CoreInteractive as={ScCoreButton} ref={ref} type={type} $variant={variant} $size={size} $overlay={overlay} $fullWidth={fullWidth} $active={active} {...rest}>
      {children}
    </CoreInteractive>
  );
});

const ButtonIconFigure = styled.div.attrs({ className: "tw-button-icon__icon" })`
  display: flex;
  align-items: center;
  justify-content: center;
`;

export interface ButtonIconProps extends Omit<CoreButtonProps, "variant" | "children"> {
  icon: IconName;
  iconSize?: number;
  "aria-label": string;
}

export const ButtonIcon = forwardRef<HTMLButtonElement, ButtonIconProps>(function ButtonIcon({ icon, iconSize = 20, ...rest }, ref) {
  return (
    <CoreButton ref={ref} variant="icon" {...rest}>
      <ButtonIconFigure>
        <SvgIcon name={icon} size={iconSize} />
      </ButtonIconFigure>
    </CoreButton>
  );
});
