// Readable username colours: with the "high contrast usernames" setting on,
// a colour is moved along the lightness axis until it reaches a contrast
// ratio of 4.5 against the theme background. Results are cached per theme.
type RGB = [number, number, number];

const BACKGROUNDS: Record<"dark" | "light", RGB> = { dark: [15, 14, 17], light: [250, 249, 250] };
const cache = new Map<string, string>();

function hexToRgb(hex: string): RGB | null {
  const m = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(hex);
  return m ? [parseInt(m[1], 16), parseInt(m[2], 16), parseInt(m[3], 16)] : null;
}

function luminance([r, g, b]: RGB): number {
  const f = (c: number) => {
    const s = c / 255;
    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
  };
  return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
}

function contrast(a: RGB, b: RGB): number {
  const la = luminance(a);
  const lb = luminance(b);
  return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
}

function rgbToHsl([r, g, b]: RGB): [number, number, number] {
  r /= 255;
  g /= 255;
  b /= 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;
  if (max === min) return [0, 0, l];
  const d = max - min;
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
  const h = max === r ? (g - b) / d + (g < b ? 6 : 0) : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
  return [h / 6, s, l];
}

function hslToRgb([h, s, l]: [number, number, number]): RGB {
  if (s === 0) return [l * 255, l * 255, l * 255];
  const q = l < 0.5 ? l * (1 + s) : l + s - l * s;
  const p = 2 * l - q;
  const hue = (t: number) => {
    if (t < 0) t += 1;
    if (t > 1) t -= 1;
    return t < 1 / 6 ? p + (q - p) * 6 * t : t < 1 / 2 ? q : t < 2 / 3 ? p + (q - p) * (2 / 3 - t) * 6 : p;
  };
  return [hue(h + 1 / 3) * 255, hue(h) * 255, hue(h - 1 / 3) * 255];
}

export function readableColor(color: string, theme: "dark" | "light"): string {
  const key = `${theme}:${color}`;
  const cached = cache.get(key);
  if (cached !== undefined) return cached;
  const rgb = hexToRgb(color);
  let result = color;
  if (rgb) {
    const bg = BACKGROUNDS[theme];
    let hsl = rgbToHsl(rgb);
    let current = rgb;
    for (let i = 0; i < 51 && contrast(current, bg) < 4.5; i++) {
      hsl = [hsl[0], hsl[1], Math.min(1, Math.max(0, hsl[2] + (theme === "dark" ? 0.01 : -0.01)))];
      current = hslToRgb(hsl);
    }
    const hex = (v: number) => Math.round(v).toString(16).padStart(2, "0");
    result = `#${hex(current[0])}${hex(current[1])}${hex(current[2])}`;
  }
  cache.set(key, result);
  return result;
}
