import type { ReactNode } from "react";
import { createGlobalStyle, ThemeProvider as ScThemeProvider } from "styled-components";
import { darkTheme, lightTheme, type Tokens } from "./theme";

const vars = (t: Tokens) => `
  --color-background-base: ${t.colors.base};
  --color-background-alt: ${t.colors.alt};
  --color-background-alt-2: ${t.colors.alt2};
  --color-background-overlay: ${t.colors.overlay};
  --color-text-base: ${t.colors.text};
  --color-text-alt: ${t.colors.textAlt};
  --color-text-alt-2: ${t.colors.textAlt2};
  --color-text-link: ${t.colors.link};
  --color-brand: ${t.colors.brand};
  --color-brand-hover: ${t.colors.brandHover};
  --color-border-base: ${t.colors.border};
  --color-background-hover: ${t.colors.hoverBg};
  --color-text-error: ${t.colors.error};
  --color-text-warn: ${t.colors.warn};
  --color-chat-highlight: ${t.colors.highlight};
  --color-chat-first: ${t.colors.highlightFirst};
  --color-gift: ${t.colors.gift};
  --shadow-elevation: ${t.shadow};
`;

const GlobalStyle = createGlobalStyle`
  html, body {
    margin: 0;
    height: 100%;
    font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    font-size: 10px;
    -webkit-font-smoothing: antialiased;
  }
  body { font-size: 1.3rem; line-height: 1.5; }
  .tw-root--theme-dark { ${vars(darkTheme)} }
  .tw-root--theme-light { ${vars(lightTheme)} }
  body { background: var(--color-background-base); color: var(--color-text-base); }
  button { font: inherit; }
  *, *::before, *::after { box-sizing: border-box; }
`;

export function ThemeProvider({ theme = "dark", children }: { theme?: "dark" | "light"; children: ReactNode }) {
  return (
    <ScThemeProvider theme={theme === "dark" ? darkTheme : lightTheme}>
      <GlobalStyle />
      {children}
    </ScThemeProvider>
  );
}
