import { Component, type CSSProperties, type KeyboardEvent, type MouseEvent, type ReactNode, type TouchEvent } from "react";
import { ButtonIcon, CoreText, Layout, SvgIcon, Tooltip } from "../core-ui";
import { LineMarker, BadgeList, CheerFragment, DisplayName, Emote, LinkFragment, MentionFragment, TextFragment } from "./fragments";
import type { LineProps } from "./line-props";
import { readableColor } from "./username-color";
import { useChatUiStore } from "./chat-ui-store";
import { MessagePartType, type BadgeRef, type ChatMessageEvent, type MessagePart } from "./types";

interface ChatLineState {
  hovered: boolean;
  focused: boolean;
  showDeleted: boolean;
  menuOpen: boolean;
}

const MENTION_RELATION_SELF = 1;

function HighlightLayer({ className }: { className: string }) {
  return (
    <Layout className={className} position="absolute" fullWidth fullHeight>
      <div className="chat-line__message-highlight-bar" />
    </Layout>
  );
}

function MessageContainer({ children }: { children: ReactNode }) {
  return (
    <Layout className="chat-line__message-container" position="relative">
      {children}
    </Layout>
  );
}

function UsernameContainer({ children }: { children: ReactNode }) {
  return (
    <Layout className="chat-line__username-container chat-line__username-container--hoverable" display="inline-block">
      {children}
    </Layout>
  );
}

function BadgeSlot({ children }: { children: ReactNode }) {
  return <span>{children}</span>;
}

function MessageBody({ children, className, style }: { children: ReactNode; className?: string; style?: CSSProperties }) {
  return (
    <span data-a-target="chat-line-message-body" dir="auto" className={className} style={style}>
      {children}
    </span>
  );
}

function FragmentList({ children }: { children: ReactNode }) {
  return <>{children}</>;
}

function ChatLineIcons({ children }: { children: ReactNode }) {
  return (
    <Layout className="chat-line__icons" display="flex" alignItems="center" position="absolute">
      {children}
    </Layout>
  );
}

function ReplyIcon({ onClick }: { onClick: () => void }) {
  return (
    <Layout className="chat-line__reply-icon chat-line__icon" display="flex">
      <Tooltip label="Reply">
        <ButtonIcon icon="reply" size="small" aria-label="Click to reply" iconSize={16} onClick={onClick} data-a-target="chat-reply-button" />
      </Tooltip>
    </Layout>
  );
}

/** A normal chat message: the class component the line dispatcher renders for message and action events. */
export class ChatLine extends Component<LineProps<ChatMessageEvent>, ChatLineState> {
  state: ChatLineState = { hovered: false, focused: false, showDeleted: false, menuOpen: false };

  rootRef: HTMLDivElement | null = null;
  touchStartedAt = 0;
  lastInteraction = "";

  setRootRef = (el: HTMLDivElement | null) => {
    this.rootRef = el;
  };
  getChatConfig = () => this.props.chatConfig;
  isAction = () => this.props.message.type === "action";
  isDeleted = () => this.props.message.deleted && !this.state.showDeleted;
  isFirstMessage = () => this.props.message.isFirstMsg;
  isHighlightedMessage = () => this.props.message.isHighlighted || this.props.message.msgId === "highlighted-message";
  isReply = () => this.props.message.reply !== null;
  isReplyTarget = () => this.props.replyHighlight?.highlightedMessageId === this.props.message.id;
  isPinned = () => this.props.pinnedChat?.pinnedMessageId === this.props.message.id;
  isMentioningMe = () => {
    const login = this.props.currentLogin;
    if (!login) return false;
    return this.props.message.messageParts.some((p) => p.type === MessagePartType.Mention && p.content.recipient.toLowerCase() === login);
  };
  getUserColor = () => {
    const { message, highContrast, theme } = this.props;
    const color = message.user.color;
    return highContrast ? readableColor(color, theme ?? "dark") : color;
  };
  getBadgeList = (): BadgeRef[] => this.props.message.user.badges;
  getAriaLabel = () => `${this.props.message.user.displayName}: ${this.props.message.body}`;
  getClassNames = () => {
    const names = ["chat-line__message"];
    if (this.isFirstMessage()) names.push("chat-line__message--first");
    if (this.isHighlightedMessage()) names.push("chat-line__message--highlighted");
    if (this.isMentioningMe()) names.push("chat-line__message--mention");
    if (this.state.hovered) names.push("chat-line__message--hovered");
    if (this.isReplyTarget()) names.push("chat-line__message--reply-target");
    if (this.isAction()) names.push("chat-line__message--action");
    return names.join(" ");
  };
  trackInteraction = (name: string) => {
    this.lastInteraction = name;
  };
  openViewerCard = (anchor: { x: number; y: number }) => {
    this.props.viewerCardContext?.openViewerCard(this.props.message.user.userID, anchor);
  };
  openMenu = () => {
    this.setState({ menuOpen: true });
    this.props.chatScroll?.setOpenMenuMessageId(this.props.message.id);
  };
  closeMenu = () => {
    this.setState({ menuOpen: false });
    this.props.chatScroll?.setOpenMenuMessageId(null);
  };

  onClick = (_e: MouseEvent<HTMLDivElement>) => {
    this.trackInteraction("click");
  };
  onDoubleClick = (e: MouseEvent<HTMLDivElement>) => {
    e.preventDefault();
    this.trackInteraction("double-click");
  };
  onMouseEnter = () => {
    this.setState({ hovered: true });
    useChatUiStore.getState().setHoveredMessage(this.props.message.id);
  };
  onMouseLeave = () => {
    this.setState({ hovered: false });
    if (useChatUiStore.getState().hoveredMessageId === this.props.message.id) useChatUiStore.getState().setHoveredMessage(null);
  };
  onFocus = () => {
    this.setState({ focused: true });
  };
  onBlur = () => {
    this.setState({ focused: false });
  };
  onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === "r" && e.altKey) this.onReplyClick();
    else if (e.key === "ContextMenu") this.openMenu();
  };
  onContextMenu = (e: MouseEvent<HTMLDivElement>) => {
    if (e.target instanceof HTMLElement && e.target.closest("a")) return;
    this.trackInteraction("context-menu");
  };
  onTouchStart = (_e: TouchEvent<HTMLDivElement>) => {
    this.touchStartedAt = Date.now();
  };
  onTouchEnd = (_e: TouchEvent<HTMLDivElement>) => {
    if (this.touchStartedAt && Date.now() - this.touchStartedAt > 500) this.openMenu();
    this.touchStartedAt = 0;
  };
  onUsernameClick = (e: MouseEvent<HTMLElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    this.openViewerCard({ x: rect.left, y: rect.bottom });
  };
  onUsernameKeyDown = (e: KeyboardEvent<HTMLElement>) => {
    if (e.key !== "Enter" && e.key !== " ") return;
    e.preventDefault();
    const rect = e.currentTarget.getBoundingClientRect();
    this.openViewerCard({ x: rect.left, y: rect.bottom });
  };
  onBadgeClick = (_badge: BadgeRef) => {
    this.trackInteraction("badge-click");
  };
  onReplyClick = () => {
    this.props.replyTray?.openReplyTray(this.props.message);
    this.props.setReplyTarget?.(this.props.message.id);
    this.trackInteraction("reply");
  };
  onLinkClick = (_url: string) => {
    this.trackInteraction("link-click");
  };
  onShowDeleted = (e: MouseEvent<HTMLElement>) => {
    e.preventDefault();
    this.setState({ showDeleted: true });
  };
  onShowDeletedKey = (e: KeyboardEvent<HTMLElement>) => {
    if (e.key === "Enter") this.setState({ showDeleted: true });
  };
  onReplyHeaderClick = () => {
    this.props.chatInputTray?.dispatchTray({ type: "focus-parent" });
  };

  renderTimestamp = (): ReactNode => {
    if (!this.props.showTimestamps) return <LineMarker show={false} className="chat-line__timestamp" />;
    const date = new Date(this.props.message.timestamp);
    const text = `${date.getUTCHours()}:${String(date.getUTCMinutes()).padStart(2, "0")}`;
    return <span className="chat-line__timestamp" data-a-target="chat-timestamp">{text}</span>;
  };
  renderBadges = (): ReactNode => <BadgeSlot>{this.getBadgeList().length ? <BadgeList badges={this.getBadgeList()} onBadgeClick={this.onBadgeClick} /> : null}</BadgeSlot>;
  renderUsername = (): ReactNode => {
    const { user } = this.props.message;
    return (
      <span className="chat-line__username" role="button" tabIndex={0} onClick={this.onUsernameClick} onKeyDown={this.onUsernameKeyDown}>
        <DisplayName user={user} color={this.getUserColor()} />
      </span>
    );
  };
  renderPart = (part: MessagePart, index: number): ReactNode => {
    switch (part.type) {
      case MessagePartType.Text:
        return <TextFragment key={index} text={part.content} />;
      case MessagePartType.Mention:
        return <MentionFragment key={index} recipient={part.content.recipient} relation={part.content.currentUserMentionRelation === MENTION_RELATION_SELF ? 1 : 0} />;
      case MessagePartType.Link:
      case MessagePartType.ClipLink:
      case MessagePartType.VideoLink: {
        const url = part.content.url;
        const text = part.type === MessagePartType.Link ? part.content.displayText : url;
        return <LinkFragment key={index} url={url} text={text} onLinkClick={this.onLinkClick} />;
      }
      case MessagePartType.Emote:
        return <Emote key={index} alt={part.content.alt} emoteID={part.content.emoteID} images={part.content.images} />;
      case MessagePartType.Cheer:
        return <CheerFragment key={index} part={part} />;
      case MessagePartType.FlaggedSegment:
        return (
          <span key={index} className="chat-line__flagged-segment">
            {part.content.parts.map(this.renderPart)}
          </span>
        );
    }
  };
  renderDeleted = (): ReactNode => (
    <>
      <span className="chat-line__message--deleted-notice" data-a-target="chat-deleted-message-placeholder">
        &lt;message deleted&gt;
      </span>
      <span> </span>
      <a className="chat-line__message--deleted-link" role="button" tabIndex={0} data-a-target="chat-deleted-message-show" onClick={this.onShowDeleted} onKeyDown={this.onShowDeletedKey}>
        show
      </a>
    </>
  );
  renderBody = (): ReactNode => (
    <MessageBody className={this.isAction() ? "chat-line__message-body--action" : undefined} style={this.isAction() ? { color: this.getUserColor() } : undefined}>
      <FragmentList>{this.isDeleted() ? this.renderDeleted() : this.props.message.messageParts.map(this.renderPart)}</FragmentList>
    </MessageBody>
  );
  renderReplyHeader = (): ReactNode => {
    const reply = this.props.message.reply;
    if (!reply) return null;
    return (
      <Layout className="chat-line__reply-header" display="flex" alignItems="center" onClick={this.onReplyHeaderClick}>
        <Layout flexShrink={0} margin={{ right: 0.5 }}>
          <SvgIcon name="reply" size={14} />
        </Layout>
        <Layout flexGrow={1} ellipsis>
          <CoreText $color="alt-2" $fontSize={7} data-a-target="chat-reply-header">
            <span>Replying to @{reply.parentDisplayName}: </span>
            <span>{reply.parentMessageBody}</span>
          </CoreText>
        </Layout>
      </Layout>
    );
  };
  renderHighlightHeader = (): ReactNode =>
    this.isHighlightedMessage() ? (
      <Layout className="chat-line__highlight-header" display="flex" alignItems="center">
        <SvgIcon name="star" size={14} />
        <CoreText $fontSize={7} $color="alt-2">
          {" "}
          Highlighted Message
        </CoreText>
      </Layout>
    ) : null;
  renderIcons = (): ReactNode => (
    <ChatLineIcons>
      <ReplyIcon onClick={this.onReplyClick} />
    </ChatLineIcons>
  );

  render() {
    const { message } = this.props;
    const reply = this.isReply();
    return (
      <Layout padding={{ x: 1, y: 0.5 }} className="chat-line__line chat-line__row" position="relative">
        <div
          className={this.getClassNames()}
          role="group"
          data-a-target="chat-line-message"
          data-a-user={message.user.userLogin}
          data-test-selector="chat-line-message"
          tabIndex={0}
          aria-label={this.getAriaLabel()}
          onClick={this.onClick}
          onDoubleClick={this.onDoubleClick}
          onMouseEnter={this.onMouseEnter}
          onMouseLeave={this.onMouseLeave}
          onFocus={this.onFocus}
          onBlur={this.onBlur}
          onKeyDown={this.onKeyDown}
          onContextMenu={this.onContextMenu}
          onTouchStart={this.onTouchStart}
          onTouchEnd={this.onTouchEnd}
          ref={this.setRootRef}
        >
          <Layout position="relative">
            <HighlightLayer className={this.isFirstMessage() ? "chat-line__message-highlight chat-line__message-highlight--first" : "chat-line__message-highlight"} />
            <MessageContainer>
              <Layout className="chat-line__reply-slot">{reply ? this.renderReplyHeader() : null}</Layout>
              {this.renderHighlightHeader()}
              <Layout>
                <Layout className="chat-line__no-background">
                  <Layout className="chat-line__message-content">
                    <LineMarker show={this.isPinned()} className="chat-line__pinned-marker" />
                    <LineMarker show={this.state.menuOpen} className="chat-line__menu-marker" />
                    <UsernameContainer>
                      {this.renderTimestamp()}
                      {this.renderBadges()}
                      {this.renderUsername()}
                    </UsernameContainer>
                    <span aria-hidden="true">{this.isAction() ? " " : ": "}</span>
                    {this.renderBody()}
                  </Layout>
                </Layout>
              </Layout>
            </MessageContainer>
            {this.renderIcons()}
          </Layout>
        </div>
      </Layout>
    );
  }
}
