import { memo, useContext } from "react";
import { connect } from "react-redux";
import { CoreInteractive, CoreLink, Layout, Tooltip } from "../core-ui";
import { AnimationSettingContext, BadgeLookupContext, BitsConfigContext, EmoteCardContext } from "./contexts";
import { compose, withContextProp } from "./hocs";
import type { RootState } from "../state/store";
import { MessagePartType, type BadgeRef, type MessagePart } from "./types";


function badgeUrls(badge: BadgeRef) {
  const base = `data/assets/badges/${badge.setID}/${badge.version}`;
  return { src: `${base}/1.png`, srcSet: `${base}/1.png 1x, ${base}/2.png 2x, ${base}/3.png 4x` };
}

export function BadgeList({ badges, onBadgeClick }: { badges: BadgeRef[]; onBadgeClick: (badge: BadgeRef) => void }) {
  const lookup = useContext(BadgeLookupContext);
  return (
    <>
      {badges.map((badge) => {
        const title = lookup.titleFor(badge.setID, badge.version) ?? badge.setID;
        const { src, srcSet } = badgeUrls(badge);
        return (
          <Tooltip key={badge.setID} label={title}>
            <CoreInteractive data-a-target="chat-badge" className="chat-badge-button" onClick={() => onBadgeClick(badge)}>
              <img alt={title} aria-label={`${title} badge`} className="chat-badge" src={src} srcSet={srcSet} decoding="auto" />
            </CoreInteractive>
          </Tooltip>
        );
      })}
    </>
  );
}
BadgeList.displayName = "BadgeList";

export interface EmoteProps {
  alt: string;
  emoteID: string;
  images: Record<string, string>;
  isInBits?: boolean;
}

interface EmoteInnerProps extends EmoteProps {
  showEmoteCard: (emoteID: string, anchor: Element) => void;
  animate: boolean;
  bitsTiers: readonly number[];
  emotesEnabled: boolean;
}

function srcSetOf(images: Record<string, string>): string {
  const sizes = ["1x", "2x", "4x"];
  return sizes
    .filter((s) => images[s])
    .map((s) => `${images[s]} ${s}`)
    .join(", ");
}

function EmoteBase({ alt, emoteID, images, showEmoteCard, animate }: EmoteInnerProps) {
  const src = images["1x"] ?? Object.values(images)[0];
  return (
    <Layout display="inline-block" className="chat-line__message--emote-button" data-a-target="emote-name">
      <img
        alt={alt}
        className={animate ? "chat-image chat-line__message--emote" : "chat-image chat-line__message--emote chat-image--static"}
        src={src}
        srcSet={srcSetOf(images)}
        decoding="auto"
        onClick={(e) => showEmoteCard(emoteID, e.currentTarget)}
      />
    </Layout>
  );
}

const withEmoteCard = withContextProp("WithEmoteCardHandler", EmoteCardContext, "emoteCard");
const withAnimation = withContextProp("WithAnimationSetting", AnimationSettingContext, "animation");
const withBitsConfig = withContextProp("WithBitsConfig", BitsConfigContext, "bitsConfig");

function EmoteAdapter(props: EmoteProps & { emoteCard: { showEmoteCard: EmoteInnerProps["showEmoteCard"] }; animation: { animate: boolean }; bitsConfig: { tiers: readonly number[] }; emotesEnabled: boolean }) {
  const { emoteCard, animation, bitsConfig, ...rest } = props;
  return <EmoteBase {...rest} showEmoteCard={emoteCard.showEmoteCard} animate={animation.animate} bitsTiers={bitsConfig.tiers} />;
}

const mapEmoteState = (state: RootState) => ({ emotesEnabled: state.chatSettings.animatedEmotes });

/** Four layers around the image: connect, the emote card handler, the animation setting and the bits config. */
export const Emote = compose(
  connect(mapEmoteState),
  withEmoteCard,
  withAnimation,
  withBitsConfig,
)(EmoteAdapter as never) as unknown as React.ComponentType<EmoteProps>;
Emote.displayName = "Emote";

export const MentionFragment = memo(function MentionFragment({ recipient, relation }: { recipient: string; relation: number }) {
  return (
    <span className={relation === 1 ? "mention-fragment mention-fragment--recipient" : "mention-fragment"} data-a-target="chat-message-mention">
      @{recipient}
    </span>
  );
});

export function LinkFragment({ url, text, onLinkClick }: { url: string; text: string; onLinkClick: (url: string) => void }) {
  const href = /^https?:\/\//.test(url) ? url : `https://${url}`;
  return (
    <CoreLink className="link-fragment" href={href} onClick={() => onLinkClick(href)} data-a-target="chat-message-link">
      {text}
    </CoreLink>
  );
}

export function CheerFragment({ part }: { part: Extract<MessagePart, { type: MessagePartType.Cheer }> }) {
  const { amount, prefix } = part.content;
  const tier = amount >= 10000 ? "10000" : amount >= 1000 ? "1000" : amount >= 100 ? "100" : "1";
  const base = `data/assets/cheers/${tier}`;
  return (
    <span className="chat-line__message--cheer" data-a-target="chat-message-cheer">
      <Layout display="inline-block">
        <img className="chat-image chat-line__message--cheer-image" alt={prefix} src={`${base}/1.png`} srcSet={`${base}/1.png 1x, ${base}/2.png 2x, ${base}/3.png 4x`} />
      </Layout>
      <span className="chat-line__message--cheer-amount">{amount}</span>
    </span>
  );
}

export function TextFragment({ text }: { text: string }) {
  return (
    <span className="text-fragment" data-a-target="chat-message-text">
      {text}
    </span>
  );
}

export function DisplayName({ user, color }: { user: { displayName: string; userLogin: string; isIntl: boolean }; color: string }) {
  return (
    <span>
      <span className="chat-author__display-name" data-a-target="chat-message-username" data-a-user={user.userLogin} data-test-selector="message-username" style={{ color }}>
        {user.displayName}
      </span>
      {user.isIntl ? <span className="chat-author__intl-login"> ({user.userLogin})</span> : null}
    </span>
  );
}

/** Renders nothing unless the line has the marker; present on every line, as the feature layers are on Twitch. */
export function LineMarker({ show, className }: { show: boolean; className: string }) {
  return show ? <span className={className} aria-hidden="true" /> : null;
}
