// Static player chrome: a <video> without a source, a poster, the control
// bar and the loading overlay. No player logic beyond local UI state.
import { memo, useState } from "react";
import { useQuery } from "@apollo/client";
import { USE_LIVE } from "../apollo/documents";
import { ICONS, type IconName } from "../shell/icons";
import { t } from "../shell/i18n";
import { CoreText, IconButton, Layout, SvgIcon, TextBlock } from "../shell/primitives";
import { useLayoutStore } from "./layout-store";
import "../styles/channel.css";

function ControlButton({ icon, label, onClick }: { icon: IconName; label: string; onClick?: () => void }) {
  return (
    <Layout color="#fff">
      <IconButton path={ICONS[icon]} label={label} onClick={onClick} target={`player-${icon}-button`} />
    </Layout>
  );
}

const QUALITIES = ["Auto", "1080p60", "720p60", "720p", "480p", "360p", "160p"];
const SPEEDS = ["0.5x", "1x", "1.5x", "2x"];

function SettingsMenu() {
  return (
    <Layout className="player-menu" role="menu" hidden display="none" data-a-target="player-settings-menu">
      {[
        ["Quality", QUALITIES],
        ["Playback speed", SPEEDS],
      ].map(([title, items]) => (
        <Layout key={title as string} padding={1}>
          <TextBlock fontSize={4} bold>
            {title as string}
          </TextBlock>
          {(items as string[]).map((item) => (
            <Layout key={item} role="menuitemradio" padding={{ y: 0.5 }}>
              <Layout as="button" display="flex" alignItems="center">
                <Layout display="flex" margin={{ right: 1 }}>
                  <SvgIcon path={ICONS.play} size={12} />
                </Layout>
                <TextBlock fontSize={3}>{item}</TextBlock>
              </Layout>
            </Layout>
          ))}
        </Layout>
      ))}
    </Layout>
  );
}

function ContentGate() {
  return (
    <Layout className="player-gate" position="absolute" style={{ top: 10, left: 10 }}>
      <Layout as="button" display="flex" alignItems="center" padding={{ x: 1, y: 0.5 }} background="overlay" borderRadius="rounded" color="#fff">
        <TextBlock fontSize={4} bold>
          Intended for certain audiences
        </TextBlock>
        <Layout display="flex" margin={{ left: 0.5 }}>
          <SvgIcon path={ICONS.chevronDown} size={16} />
        </Layout>
      </Layout>
    </Layout>
  );
}

function OverlayLayers() {
  return (
    <>
      {[0, 1, 2].map((i) => (
        <Layout key={i} className="player-overlay-background" position="absolute" fullWidth fullHeight style={{ inset: 0, pointerEvents: "none" }}>
          <Layout fullWidth fullHeight>
            <Layout fullWidth fullHeight />
          </Layout>
        </Layout>
      ))}
      <Layout className="extension-overlay" position="absolute" fullWidth fullHeight style={{ inset: 0, pointerEvents: "none" }}>
        <Layout className="extension-view" fullWidth fullHeight>
          <Layout className="extension-view__iframe-container" fullWidth fullHeight>
            <Layout className="extension-view__placeholder" />
          </Layout>
        </Layout>
      </Layout>
      <Layout className="ad-container" position="absolute" display="none" hidden>
        <Layout padding={1}>
          <TextBlock fontSize={3}>Ad</TextBlock>
        </Layout>
      </Layout>
    </>
  );
}

function VolumeSlider({ value, onChange }: { value: number; onChange: (v: number) => void }) {
  return (
    <Layout className="player-volume" data-a-target="player-volume-slider">
      <Layout className="player-volume__hit-area" fullWidth>
      <Layout className="player-volume__track">
        <Layout className="player-volume__fill" style={{ width: `${value * 100}%` }} />
        <Layout className="player-volume__thumb" style={{ left: `${value * 100}%` }} />
      </Layout>
      <input
        className="player-volume__input"
        type="range"
        min={0}
        max={1}
        step={0.01}
        value={value}
        aria-label={t("player.volume")}
        onChange={(e) => onChange(Number(e.target.value))}
      />
      </Layout>
    </Layout>
  );
}

function StatusOverlay({ live }: { live: boolean }) {
  return (
    <Layout className="player-status" data-a-target="player-overlay-loading">
      <Layout display="flex" flexDirection="column" alignItems="center" gap={1}>
        <Layout className="player-spinner" />
        <CoreText fontSize={5} bold color="#fff">
          {live ? t("player.loading") : t("channel.offline")}
        </CoreText>
      </Layout>
    </Layout>
  );
}

export const Player = memo(function Player({ login }: { login: string }) {
  const [paused, setPaused] = useState(true);
  const [volume, setVolume] = useState(0.5);
  const [muted, setMuted] = useState(true);
  const theatre = useLayoutStore((s) => s.theatreMode);
  const { data } = useQuery(USE_LIVE, { variables: { channelLogin: login } });
  const live = Boolean(data?.user?.stream);
  return (
    <Layout className={`channel-root__player-container ${theatre ? "channel-root__player-container--theatre" : ""}`} data-a-target="video-player-layout">
      <Layout className="video-player" data-a-target="video-player" data-a-player-type="site">
        <Layout className="video-player__container" data-test-selector="video-player__container">
          <video className="video-player__video" poster={`data/assets/posters/${login}.png`} playsInline muted={muted} preload="none" data-a-target="video-ref" />
          <Layout className="video-player__overlay" data-a-target="player-overlay">
            <OverlayLayers />
            <ContentGate />
            <Layout position="absolute" style={{ top: 10, right: 10 }}>
              {live ? (
                <Layout display="flex" alignItems="center" className="live-indicator">
                  <Layout className="live-tag" as="span" padding={{ x: 0.5 }}>
                    <TextBlock fontSize={3} bold>
                      {t("channel.live")}
                    </TextBlock>
                  </Layout>
                </Layout>
              ) : null}
            </Layout>
            <StatusOverlay live={live} />
            <SettingsMenu />
            <Layout className="player-controls" data-a-target="player-controls">
              <Layout className="player-controls__group">
                <ControlButton icon={paused ? "play" : "pause"} label={paused ? t("player.play") : t("player.pause")} onClick={() => setPaused((p) => !p)} />
                <ControlButton icon={muted ? "mute" : "volume"} label={t("player.mute")} onClick={() => setMuted((m) => !m)} />
                <VolumeSlider value={volume} onChange={setVolume} />
              </Layout>
              <Layout className="player-controls__group">
                <ControlButton icon="clip" label={t("player.clip")} />
                <ControlButton icon="bell" label="Captions" />
                <ControlButton icon="share" label="Picture in picture" />
                <ControlButton icon="star" label="Stream stats" />
                <ControlButton icon="settings" label={t("player.settings")} />
                <ControlButton icon="theatre" label={t("player.theatre")} />
                <ControlButton icon="fullscreen" label={t("player.fullscreen")} />
              </Layout>
            </Layout>
          </Layout>
        </Layout>
      </Layout>
    </Layout>
  );
});
