import { ButtonIcon, CoreButton, CoreText, Layout, Tooltip } from "../core-ui";
import { useChatUiStore } from "./chat-ui-store";

/** The input area as signed-out viewers see it: a placeholder box that asks them to log in, plus the settings and points buttons. */
export function ChatInput() {
  const replyMessage = useChatUiStore((s) => s.replyMessage);
  return (
    <Layout className="chat-input tw-block" padding={{ x: 1, bottom: 1 }} position="relative" data-test-selector="chat-input-area">
      {replyMessage ? <ReplyTray /> : null}
      <Layout className="chat-wysiwyg-input" position="relative" padding={{ bottom: 1 }}>
        <div className="chat-wysiwyg-input__box" data-a-target="chat-input-box">
          <div className="chat-wysiwyg-input__placeholder" data-a-target="chat-input-placeholder">
            Log in to chat
          </div>
          <div
            className="chat-wysiwyg-input__editor"
            data-a-target="chat-input"
            data-test-selector="chat-input"
            role="textbox"
            aria-label="Log in to chat"
            aria-multiline="true"
            contentEditable
            suppressContentEditableWarning
            spellCheck
            tabIndex={0}
            autoCorrect="off"
            onBeforeInput={(e) => e.preventDefault()}
          />
        </div>
      </Layout>
      <Layout className="chat-input__buttons-container" display="flex" justifyContent="between" alignItems="center">
        <Layout display="flex" alignItems="center">
          <Tooltip label="Channel Points" placement="top">
            <ButtonIcon icon="points" aria-label="Channel points" data-a-target="channel-points-button" />
          </Tooltip>
          <Tooltip label="Bits and gifts" placement="top">
            <ButtonIcon icon="gift" aria-label="Gift a subscription" data-a-target="gift-button" />
          </Tooltip>
        </Layout>
        <Layout display="flex" alignItems="center">
          <Tooltip label="Chat settings" placement="top">
            <ButtonIcon icon="settings" aria-label="Chat settings" data-a-target="chat-settings" />
          </Tooltip>
          <Layout margin={{ left: 0.5 }}>
            <CoreButton variant="primary" data-a-target="chat-send-button" disabled>
              Chat
            </CoreButton>
          </Layout>
        </Layout>
      </Layout>
    </Layout>
  );
}

function ReplyTray() {
  const replyMessage = useChatUiStore((s) => s.replyMessage);
  const close = useChatUiStore((s) => s.closeReplyTray);
  if (!replyMessage) return null;
  return (
    <Layout className="chat-input-tray" background="alt-2" borderRadius="medium" padding={1} margin={{ bottom: 1 }} display="flex" alignItems="center" data-a-target="chat-input-tray-reply">
      <Layout flexGrow={1} ellipsis>
        <CoreText $fontSize={7} $color="alt-2">
          Replying to @{replyMessage.user.displayName}: {replyMessage.body}
        </CoreText>
      </Layout>
      <ButtonIcon icon="close" size="small" iconSize={14} aria-label="Cancel reply" onClick={close} />
    </Layout>
  );
}
