import { graphql } from "@apollo/client/react/hoc";
import { connect } from "react-redux";
import { ChatLineUserQuery } from "../apollo/chat-queries";
import { withLineQueries } from "../apollo/line-queries";
import { compose } from "./hocs";
import { LineDispatcher } from "./lines";
import type { LineProps } from "./line-props";
import type { ComponentType } from "react";

/**
 * The wrapper around every line, as Twitch's `iL`: a pure Redux connect around
 * an Apollo cache-only query around the line dispatcher. The connect compares
 * props shallowly, so a list render only reaches the line when its message
 * changed.
 */
export const ChatLineStack = compose(
  connect(() => ({ fadeSharedChats: false })),
  graphql<{ message: LineProps["message"] }>(ChatLineUserQuery, {
    options: ({ message }) => ({ variables: { userID: ("user" in message && message.user ? message.user.userID : "") || "0" }, fetchPolicy: "cache-only" }),
  }),
  withLineQueries,
)(LineDispatcher as never) as unknown as ComponentType<{ message: LineProps["message"]; messageHash?: string }>;
