  resub: "resubscription",
  subgift: "subgift",
  anonsubgift: "subgift",
  submysterygift: "submysterygift",
  anonsubmysterygift: "submysterygift",
  giftpaidupgrade: "giftpaidupgrade",
  anongiftpaidupgrade: "giftpaidupgrade",
  primepaidupgrade: "giftpaidupgrade",
