import { graphql, type ChildDataProps } from "@apollo/client/react/hoc";
import { ABOUT_PANEL } from "../apollo/documents";
import { ICONS } from "../shell/icons";
import { t } from "../shell/i18n";
import { CoreImage, CoreText, InjectLayout, Layout, SvgIcon, TextBlock, Tooltip } from "../shell/primitives";

interface AboutData {
  user: {
    id: string;
    description: string;
    displayName: string;
    followers: { totalCount: number };
    channel: { socialMedias: { id: string; name: string; title: string; url: string }[] };
    lastBroadcast: { game: { displayName: string } | null } | null;
  } | null;
}

type Props = ChildDataProps<{ login: string }, AboutData, { channelLogin: string; skipSchedule: boolean }>;

function Panel({ index, login }: { index: number; login: string }) {
  return (
    <Layout className="channel-panel" as="section" data-a-target={`panel-${index}`}>
      <Layout padding={1}>
        <Layout display="flex" alignItems="center" gap={0.5}>
          <TextBlock fontSize={4} bold>
            {t("about.title", { name: `${login} #${index + 1}` })}
          </TextBlock>
        </Layout>
      </Layout>
      <Layout>
        <Layout>
          <CoreImage src={`data/assets/thumbs/${login}-320x180.png`} alt="" loading="lazy" />
        </Layout>
      </Layout>
      <Layout padding={1}>
        <Layout>
          <TextBlock fontSize={3} color="text-alt-2">
            {"Panel text ".repeat(6)}
          </TextBlock>
        </Layout>
      </Layout>
    </Layout>
  );
}

function AboutPanelView({ data, login }: Props) {
  const user = data.user;
  if (!user) return null;
  return (
    <Layout className="about-panel" as="section" data-a-target="about-panel">
      <Layout display="flex" alignItems="center" gap={1}>
        <SvgIcon path={ICONS.person} size={24} />
        <CoreText as="h2" fontSize={6} bold>
          {t("about.title", { name: user.displayName })}
        </CoreText>
      </Layout>
      <Layout margin={{ top: 1 }}>
        <CoreText as="span" fontSize={5} bold data-a-target="about-panel-follower-count">
          {t("followers.count", { count: user.followers.totalCount })}
        </CoreText>
      </Layout>
      <Layout margin={{ top: 1 }}>
        <CoreText fontSize={4} color="text-alt">
          {user.description}
        </CoreText>
      </Layout>
      <Layout display="flex" flexWrap="wrap" gap={1} margin={{ top: 1 }}>
        {user.channel.socialMedias.map((s) => (
          <InjectLayout key={s.id}>
            <a className="social-media-link tw-link" href={s.url} rel="noopener noreferrer" target="_blank">
              <Layout display="flex" alignItems="center" gap={0.5}>
                <Tooltip label={s.title}>
                  <Layout display="flex">
                    <SvgIcon path={ICONS.share} size={16} />
                  </Layout>
                </Tooltip>
                <CoreText as="span" fontSize={4} color="text-link">
                  {s.title}
                </CoreText>
              </Layout>
            </a>
          </InjectLayout>
        ))}
      </Layout>
      <Layout className="channel-schedule" margin={{ top: 2 }} data-a-target="channel-schedule">
        <Layout display="flex" alignItems="center" gap={1}>
          <SvgIcon path={ICONS.clip} size={20} />
          <TextBlock fontSize={5} bold>
            Schedule
          </TextBlock>
        </Layout>
        {["Mon", "Wed", "Fri", "Sat"].map((day) => (
          <Layout key={day} display="flex" justifyContent="space-between" padding={{ y: 0.5 }}>
            <Layout>
              <TextBlock fontSize={4}>{day}</TextBlock>
            </Layout>
            <Layout>
              <TextBlock fontSize={4} color="text-alt-2">
                8:00 PM
              </TextBlock>
            </Layout>
          </Layout>
        ))}
      </Layout>
      <Layout className="channel-panels" data-a-target="channel-panels">
        {[0, 1, 2, 3, 4, 5].map((i) => (
          <Panel key={i} index={i} login={login} />
        ))}
      </Layout>
    </Layout>
  );
}

export const AboutPanel = graphql<{ login: string }, AboutData, { channelLogin: string; skipSchedule: boolean }, Props>(ABOUT_PANEL, {
  options: ({ login }) => ({ variables: { channelLogin: login, skipSchedule: true } }),
})(AboutPanelView as never) as unknown as React.ComponentType<{ login: string }>;
