import styled from "styled-components";

interface CoreLinkProps {
  $color?: "link" | "inherit";
  $underline?: boolean;
  $external?: boolean;
}

export const CoreLink = styled.a.attrs<CoreLinkProps>((p) => ({
  className: "tw-link",
  rel: p.$external === false ? undefined : "noopener noreferrer",
  target: p.$external === false ? undefined : "_blank",
}))<CoreLinkProps>`
  color: ${({ theme, $color }) => ($color === "inherit" ? "inherit" : theme.colors.link)};
  text-decoration: ${({ $underline }) => ($underline ? "underline" : "none")};
  cursor: pointer;
  &:hover {
    text-decoration: underline;
  }
  &:focus-visible {
    outline: 2px solid ${({ theme }) => theme.colors.brand};
  }
`;
