import { Component, Profiler } from "react";
import { Layout } from "../core-ui";
import { setTimeout, clearTimeout } from "../platform/timers";
import type { MessageBufferAPI } from "./buffer-api";
import { ChatScroller, type MessageHandlerAPI } from "./ChatScroller";
import { ChatLineStack } from "./line-stack";
import type { ChatEvent } from "./types";

interface ChatListProps {
  buffer: MessageBufferAPI;
  messageHandlerAPI: MessageHandlerAPI;
  chatPerformanceFlag: boolean;
}

interface ChatListState {
  messages: ChatEvent[];
}


const noop = () => {};

/** Owns the visible window of messages and renders it, one keyed line per message. */
export class ChatList extends Component<ChatListProps, ChatListState> {
  state: ChatListState = { messages: this.props.buffer.getMessages() };
  syncHandle: number | null = null;
  unsubscribe: (() => void) | null = null;

  componentDidMount() {
    this.unsubscribe = this.props.buffer.subscribe(this.onBufferUpdate);
    this.syncBufferedMessages();
  }

  componentWillUnmount() {
    this.unsubscribe?.();
    if (this.syncHandle !== null) clearTimeout(this.syncHandle);
  }

  onBufferUpdate = () => {
    if (this.syncHandle === null) this.syncHandle = setTimeout(this.syncBufferedMessages, 0);
  };

  syncBufferedMessages = () => {
    this.syncHandle = null;
    this.setState({ messages: this.props.buffer.getMessages() });
  };

  mapMessagesToChatLines = (messages: ChatEvent[]) =>
    messages.map((message) => {
      // The serialized message only serves as a change hash when the performance flag is on, but it is computed on every render.
      const messageHash = JSON.stringify(message);
      return (
        <Layout key={message.id}>
          <Profiler id="chat-line" onRender={noop}>
            <ChatLineStack message={message} messageHash={messageHash} />
          </Profiler>
        </Layout>
      );
    });

  render() {
    const { messages } = this.state;
    const last = messages[messages.length - 1];
    const messagesHash = `${messages.length}:${last ? last.id : ""}:${messages[0] ? messages[0].id : ""}`;
    return (
      <ChatScroller buffer={this.props.buffer} messageHandlerAPI={this.props.messageHandlerAPI} messagesHash={messagesHash}>
        {this.mapMessagesToChatLines(messages)}
      </ChatScroller>
    );
  }
}
