// The chat message buffer, with the semantics of Twitch's MessageBuffer:
// incoming events wait in a delayed buffer, a 200 ms flush moves them into the
// buffer, and subscribers hear about a flush only when it changed something.
// Deletions and bans mark events in place, in every buffer that holds them.
import { setInterval, clearInterval, setTimeout, clearTimeout, now } from "../platform/timers";
import { PauseReason, type MessageBufferAPI } from "./buffer-api";
import { onMessageDeleteSuccess } from "../apollo/message-cache";
import { ChatEventType, type ChatEvent, type ChatMessageEvent } from "./types";

const VISIBLE = 150;
const PAUSED_MAX = 900;
const LOAD_NEWER_STEP = 40;
const HIGHLIGHT_MAX = 99;
const FLUSH_INTERVAL = 200;
const RATE_INTERVAL = 1000;
const RATE_WINDOW = 3;
const MODERATED_USER_GUARD = 1000;

export type HighlightKind = "mention" | "firstMessage" | "highlighted";

export interface MessageBuffer extends MessageBufferAPI {
  /** Takes one event from the chat connection. */
  handleEvent(event: ChatEvent): void;
  hasNewerLeft(): boolean;
  /** The last (at most 99) events of one highlight type, oldest first. */
  getHighlights(kind: HighlightKind): ChatEvent[];
}

interface DelayedEntry {
  event: ChatEvent;
  time: number;
  shouldDelay: boolean;
}

function asMessage(event: ChatEvent): ChatMessageEvent | null {
  return event.type === ChatEventType.Message || event.type === ChatEventType.Action ? (event as ChatMessageEvent) : null;
}

function highlightKinds(event: ChatEvent): HighlightKind[] {
  const message = asMessage(event);
  if (!message) return [];
  const kinds: HighlightKind[] = [];
  if (message.isMentioningCurrentUser) kinds.push("mention");
  if (message.isFirstMsg) kinds.push("firstMessage");
  if (message.isHighlighted) kinds.push("highlighted");
  return kinds;
}

class MessageBufferImpl implements MessageBuffer {
  private buffer: ChatEvent[] = [];
  private delayedBuffer: DelayedEntry[] = [];
  private delayedHighlights: Partial<Record<HighlightKind, DelayedEntry[]>> = {};
  private highlights: Partial<Record<HighlightKind, ChatEvent[]>> = {};
  private listeners: Array<() => void> = [];
  private paused = false;
  private reason: PauseReason | null = null;
  private slidingWindowEnd = 0;
  private uncountedMessages = 0;
  private rateMeasurements: number[] = [];
  private readonly moderatedUsers = new Set<string>();
  private readonly blockedUsers = new Set<string>();
  private readonly unhideUsers = new Set<string>();
  private readonly guardTimers = new Set<number>();
  private readonly delayDuration = 0;
  private readonly currentUserLogin: string | null = null;
  private readonly shouldSeeDeleted = true;
  private readonly flushInterval: number;
  private readonly rateInterval: number;

  constructor(readonly channel: string) {
    this.flushInterval = setInterval(() => this.flushRawMessages(), FLUSH_INTERVAL);
    this.rateInterval = setInterval(() => this.measureChatRate(), RATE_INTERVAL);
  }

  getMessages(): ChatEvent[] {
    return this.buffer.slice(0, VISIBLE);
  }

  subscribe(listener: () => void): () => void {
    if (this.listeners.indexOf(listener) === -1) this.listeners = this.listeners.concat(listener);
    return () => {
      this.listeners = this.listeners.filter((l) => l !== listener);
    };
  }

  isPaused(): boolean {
    return this.paused;
  }

  pauseReason(): PauseReason | null {
    return this.paused ? this.reason : null;
  }

  pause(reason: PauseReason): void {
    this.reason = reason;
    this.setPaused(true);
  }

  unpause(): void {
    if (!this.paused) return;
    this.paused = false;
    this.reason = null;
    this.clear(VISIBLE);
    this.slidingWindowEnd = Math.min(VISIBLE, this.buffer.length);
    this.notifySubscribers();
  }

  unreadCount(): number {
    return Math.max(0, this.buffer.length - this.slidingWindowEnd);
  }

  hasNewerLeft(): boolean {
    return this.slidingWindowEnd < this.buffer.length;
  }

  loadNewer(): void {
    if (!this.hasNewerLeft()) return;
    const end = Math.min(this.buffer.length, this.slidingWindowEnd + LOAD_NEWER_STEP);
    const dropped = Math.max(0, end - VISIBLE);
    this.clear(this.buffer.length - dropped);
    this.slidingWindowEnd = end - dropped;
    this.notifySubscribers();
  }

  loadNewest(): void {
    this.paused = false;
    this.reason = null;
    this.clear(VISIBLE);
    this.slidingWindowEnd = Math.min(VISIBLE, this.buffer.length);
    this.notifySubscribers();
  }

  chatRate(): number {
    if (this.rateMeasurements.length === 0) return 0;
    return this.rateMeasurements.reduce((sum, n) => sum + n) / this.rateMeasurements.length;
  }

  getHighlights(kind: HighlightKind): ChatEvent[] {
    return this.highlights[kind]?.slice() ?? [];
  }

  dispose(): void {
    clearInterval(this.flushInterval);
    clearInterval(this.rateInterval);
    for (const id of this.guardTimers) clearTimeout(id);
    this.guardTimers.clear();
    this.buffer = [];
    this.delayedBuffer = [];
    this.notifySubscribers();
    this.listeners = [];
  }

  handleEvent(event: ChatEvent): void {
    if (this.messageIncludesBlockedUser(event)) return;
    this.sanitizeBlockedReplyParent(event);
    let shouldDelay = true;
    switch (event.type) {
      case ChatEventType.Message:
      case ChatEventType.Action: {
        const message = event as ChatMessageEvent;
        if (message.id && this.hasMessage(message.id)) return;
        this.uncountedMessages++;
        shouldDelay = !this.isOwnMessage(message);
        break;
      }
      case ChatEventType.Moderation:
        if (!this.handleModeration(event)) return;
        break;
      case ChatEventType.ChatCleared:
        this.clear();
        break;
      case ChatEventType.Disconnected:
        return;
      case ChatEventType.Reconnect:
        if (this.buffer.some((e) => e.id === event.id) || this.delayedBuffer.some((d) => d.event.id === event.id)) return;
        break;
      default:
        break;
    }
    const entry: DelayedEntry = { event, time: now(), shouldDelay };
    this.delayedBuffer.push(entry);
    this.maybePushToDelayedHighlights(entry);
  }

  private messageIncludesBlockedUser(event: ChatEvent): boolean {
    for (const id of this.userIDsOf(event)) {
      if (this.blockedUsers.has(id) && !this.unhideUsers.has(id)) return true;
    }
    return false;
  }

  private userIDsOf(event: ChatEvent): string[] {
    const message = asMessage(event);
    if (!message) return [];
    const ids = [message.user.userID];
    if (message.reply) ids.push(message.reply.parentUid);
    return ids;
  }

  private sanitizeBlockedReplyParent(event: ChatEvent): void {
    const message = asMessage(event);
    if (message && message.reply && this.blockedUsers.has(message.reply.parentUid)) {
      message.reply = { ...message.reply, parentDisplayName: "User Hidden", parentMessageBody: "<message hidden from blocked user>" };
    }
  }

  private isOwnMessage(message: ChatMessageEvent): boolean {
    const login = this.currentUserLogin;
    return !!login && !!message.user && message.user.userLogin === login;
  }

  private passesDeletionChecks(event: ChatEvent): boolean {
    const deleted = (event as { deleted?: boolean }).deleted;
    return this.shouldSeeDeleted || deleted === undefined || !deleted;
  }

  private maybeAddHistorySeparator(event: ChatEvent): boolean {
    const last = this.buffer[this.buffer.length - 1];
    if (!last || last.type !== ChatEventType.Connected || event.type === ChatEventType.Connected) return false;
    if (this.buffer.find((e) => e.type === ChatEventType.LiveSeparator)) return false;
    this.buffer.push({ type: ChatEventType.LiveSeparator, id: `live-message-separator-${this.buffer.length}` } as ChatEvent);
    return true;
  }

  private hasMessage(id: string): boolean {
    const isMessage = (e: ChatEvent) => (e.type === ChatEventType.Message || e.type === ChatEventType.Action) && e.id === id;
    return this.buffer.some(isMessage) || this.delayedBuffer.some((d) => isMessage(d.event));
  }

  /**
   * Marks events in place; deleted events stay in the buffers, for the UI to show as deleted.
   * Returns false when the event itself should not be shown.
   */
  private handleModeration(event: ChatEvent): boolean {
    const params = (event as { params: Record<string, string> }).params;
    const lists = (): ChatEvent[][] => [this.buffer, this.delayedBuffer.map((d) => d.event), ...Object.values(this.highlights)];
    if (params.action === "delete") {
      for (const list of lists()) {
        const target = list.find((e) => asMessage(e) !== null && e.id === params.targetMsgId);
        if (target) {
          (target as ChatMessageEvent).deleted = true;
          onMessageDeleteSuccess(target as ChatMessageEvent);
        }
      }
      return false;
    }
    const login = params.login;
    if (this.moderatedUsers.has(login)) return false;
    for (const list of lists()) {
      for (const e of list) {
        const message = asMessage(e);
        if (message && message.user.userLogin === login) {
          message.deleted = true;
          message.banned = true;
          onMessageDeleteSuccess(message);
        }
      }
    }
    this.moderatedUsers.add(login);
    const id = setTimeout(() => {
      this.moderatedUsers.delete(login);
      this.guardTimers.delete(id);
    }, MODERATED_USER_GUARD);
    this.guardTimers.add(id);
    return true;
  }

  private maybePushToDelayedHighlights(entry: DelayedEntry): void {
    for (const kind of highlightKinds(entry.event)) {
      (this.delayedHighlights[kind] ??= []).push(entry);
    }
  }

  private shouldDelayMessage(entry: DelayedEntry): boolean {
    return entry.shouldDelay && entry.time > now() - this.delayDuration;
  }

  private flushRawMessages(): void {
    const remaining: DelayedEntry[] = [];
    const before = this.buffer.length;
    let trimmed = 0;
    for (const entry of this.delayedBuffer) {
      if (this.shouldDelayMessage(entry)) {
        remaining.push(entry);
      } else if (this.passesDeletionChecks(entry.event)) {
        this.maybeAddHistorySeparator(entry.event);
        this.buffer.push(entry.event);
        if (!this.paused) {
          if (this.buffer.length > VISIBLE) trimmed++;
          else this.slidingWindowEnd++;
        }
      }
    }
    this.delayedBuffer = remaining;
    this.flushHighlights();
    if (this.buffer.length > before) {
      this.clear(Math.min(PAUSED_MAX, this.buffer.length - trimmed));
      this.notifySubscribers();
    }
  }

  private flushHighlights(): void {
    const remaining: Partial<Record<HighlightKind, DelayedEntry[]>> = {};
    for (const kind of Object.keys(this.delayedHighlights) as HighlightKind[]) {
      for (const entry of this.delayedHighlights[kind] ?? []) {
        if (this.shouldDelayMessage(entry)) (remaining[kind] ??= []).push(entry);
        else (this.highlights[kind] ??= []).push(entry.event);
      }
      if (this.highlights[kind]) this.highlights[kind] = this.highlights[kind]!.slice(-HIGHLIGHT_MAX);
    }
    this.delayedHighlights = remaining;
  }

  private measureChatRate(): void {
    if (this.rateMeasurements.length === RATE_WINDOW) this.rateMeasurements.shift();
    this.rateMeasurements.push(this.uncountedMessages);
    this.uncountedMessages = 0;
  }

  /** Keeps the newest `keep` events; `keep <= 0` empties the buffers and unpauses. */
  private clear(keep = 0): void {
    if (keep <= 0) {
      this.buffer = [];
      this.delayedBuffer = [];
      this.slidingWindowEnd = 0;
      this.paused = false;
      this.reason = null;
      return;
    }
    if (this.paused && this.buffer.length >= PAUSED_MAX) {
      this.paused = false;
      this.reason = null;
      keep = VISIBLE;
      this.slidingWindowEnd = Math.min(VISIBLE, this.buffer.length);
    }
    if (keep < this.buffer.length) this.buffer = this.buffer.slice(-keep);
  }

  private setPaused(paused: boolean): void {
    if (this.paused === paused) return;
    this.paused = paused;
    if (!paused) this.slidingWindowEnd = Math.min(this.buffer.length, VISIBLE);
    this.notifySubscribers();
  }

  private notifySubscribers(): void {
    for (const listener of this.listeners) listener();
  }
}

export function createMessageBuffer(channel: string): MessageBuffer {
  return new MessageBufferImpl(channel);
}
