import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { Helmet } from "react-helmet";
import { useQuery } from "@apollo/client";
import { CHANNEL_SHELL } from "../apollo/documents";
import { setPageChannel } from "../apollo/page-resolvers";
import { ChannelChat } from "../chat/ChannelChat";
import { emitStepEvent } from "../workload/events";
import { BackgroundQueries } from "../shell/BackgroundQueries";
import { t } from "../shell/i18n";
import { Layout } from "../shell/primitives";
import { ChannelInfo } from "./ChannelInfo";
import { Player } from "./Player";
import "../styles/channel.css";

let visits = 0;

function ChannelRoot({ login }: { login: string }) {
  const { data } = useQuery(CHANNEL_SHELL, { variables: { login } });
  const shell = data?.userOrError;
  useEffect(() => {
    if (shell?.login === login) emitStepEvent("navigate-finish", login);
  }, [shell, login]);
  const [context] = useState<"home-to-channel" | "channel-to-channel">(() => (visits++ === 0 ? "home-to-channel" : "channel-to-channel"));
  return (
    <>
      <Helmet>
        <title>{t("channel.title", { name: shell?.displayName ?? login })}</title>
      </Helmet>
      <Layout className="channel-root" data-a-target="channel-root" data-channel={login}>
        <Layout className="channel-root__main" data-a-target="channel-root-main">
          <Player login={login} />
          <ChannelInfo login={login} />
        </Layout>
        <Layout as="aside" className="channel-root__right-column" data-a-target="right-column">
          <ChannelChat login={login} />
        </Layout>
      </Layout>
      <BackgroundQueries key={login} login={login} context={context} />
    </>
  );
}

export default function ChannelPage() {
  const { login = "" } = useParams();
  setPageChannel(login);
  return <ChannelRoot key={login} login={login} />;
}
