// The Apollo work that Twitch's chat lines do besides the cache-only user
// query. Every message line mounts three more `useQuery` hooks, which are
// skipped for a signed-out viewer but still create an observable query and a
// query info in the QueryManager (two allow-list lookups of the highlight
// hook and the permission lookup). Every render of a line also reads two
// queries that are not in the cache. So the cache holds about four query
// infos per line, and each line that unmounts makes `broadcastQueries` visit
// all of them.
import { useApolloClient, useQuery } from "@apollo/client";
import { useMemo, type ComponentType } from "react";
import { ChatEventType } from "../chat/types";
import type { ChatEvent } from "../chat/types";
import { ChannelPermissionSet, ChatHighlightSettings, CommunityOnboardingAllowlist, LowTrustUserProperties } from "./line-documents";

interface AllowListData {
  communityOnboarding?: { channelAllowLists?: { experimentName: string }[] } | null;
}

interface PermissionData {
  channel?: { permissionResults?: { permission: string; hasPermission: boolean }[] } | null;
}

function useChannelAllowList(channelID: string, skip: boolean): { experimentName: string }[] {
  const result = useQuery<AllowListData>(CommunityOnboardingAllowlist, { variables: { channelID }, skip });
  const lists = result.data?.communityOnboarding?.channelAllowLists;
  return lists?.length ? lists : [];
}

function useChannelPermissions(channelID: string, userID: string, permissions: readonly string[], skip: boolean) {
  const sorted = useMemo(() => Array.from(new Set(permissions)).sort(), [permissions.join("|")]);
  const { data, loading, refetch } = useQuery<PermissionData>(ChannelPermissionSet, {
    variables: { channelID, userID, permissions: sorted },
    skip: skip || sorted.length === 0,
  });
  const granted = new Map(data?.channel?.permissionResults?.map((r) => [r.permission, r.hasPermission]));
  const out: Record<string, boolean> = {};
  for (const p of sorted) out[p] = granted.get(p) ?? false;
  return { permissions: out, loading, refetch };
}

const LINE_PERMISSIONS = ["MODERATE", "DELETE_MESSAGE", "TIMEOUT_USER"] as const;

function isMessage(message: ChatEvent): boolean {
  return message.type === ChatEventType.Message || message.type === ChatEventType.Action;
}

/** Wraps the line dispatcher with the extra query hooks and cache reads that each message line makes. */
export function withLineQueries<P extends { message: ChatEvent }>(Wrapped: ComponentType<P>): ComponentType<P> {
  const WithLineQueries = (props: P) => {
    const client = useApolloClient();
    const message = props.message;
    const roomID = isMessage(message) ? (message as { roomID: string }).roomID : "";
    const userID = isMessage(message) ? (message as { user: { userID: string } }).user.userID : "";
    useChannelAllowList(roomID, true);
    useChannelAllowList(roomID, true);
    useChannelPermissions(roomID, "", LINE_PERMISSIONS, true);
    if (roomID) {
      client.readQuery({ query: LowTrustUserProperties, variables: { channelID: roomID, targetUserID: userID } });
      client.readQuery({ query: ChatHighlightSettings });
    }
    return <Wrapped {...props} />;
  };
  WithLineQueries.displayName = `WithLineQueries(${Wrapped.displayName ?? Wrapped.name ?? "Component"})`;
  return WithLineQueries;
}
