// What Twitch's message buffer writes into the Apollo cache when a message is
// deleted (by a moderator or by a ban): the message is stored under the
// `ChatReplies` query with a `deletedAt` stamp, so the viewer card and reply
// views can show it as deleted. The write makes the cache rebroadcast to every
// watched query.
import { gql } from "@apollo/client";
import type { ChatMessageEvent } from "../chat/types";
import { getApolloClient } from "./client";

export const ChatReplies = gql`
  query ChatReplies($messageID: ID!) {
    message(id: $messageID) {
      id
      sentAt
      deletedAt
      content {
        text
        fragments {
          text
        }
      }
      sender {
        id
        login
        displayName
      }
      senderBadges {
        setID
        version
        id
      }
      senderChatColor
      replies {
        totalCount
        nodes {
          id
          sentAt
          deletedAt
        }
      }
    }
  }
`;

interface RepliesData {
  message: { replies: { nodes: { id: string; deletedAt: string | null }[] } | null } | null;
}

export function onMessageDeleteSuccess(message: ChatMessageEvent): void {
  const client = getApolloClient();
  if (!client) return;
  const parentID = message.reply ? message.reply.threadParentMsgId : message.id;
  let existing: RepliesData | null;
  try {
    existing = client.readQuery<RepliesData>({ query: ChatReplies, variables: { messageID: parentID } });
  } catch {
    return;
  }
  const deletedAt = new Date().toISOString();
  if (!existing) {
    client.writeQuery({
      query: ChatReplies,
      variables: { messageID: message.id },
      data: {
        message: {
          __typename: "Message",
          id: message.id,
          sentAt: new Date(message.timestamp).toISOString(),
          deletedAt,
          replies: null,
          content: {
            __typename: "MessageContent",
            text: message.body,
            fragments: message.messageParts.map((part) => ({ __typename: "MessageFragment", text: typeof part.content === "string" ? part.content : "" })),
          },
          sender: { __typename: "User", id: message.user.userID, login: message.user.userLogin, displayName: message.user.displayName },
          senderBadges: message.user.badges.map((b) => ({ __typename: "Badge", id: `${b.setID}/${b.version}`, setID: b.setID, version: b.version })),
          senderChatColor: message.user.color || null,
        },
      },
    });
  }
  if (message.reply) {
    const nodes = existing?.message?.replies?.nodes;
    const index = nodes ? nodes.findIndex((n) => n.id === message.id) : -1;
    if (existing && nodes && index >= 0) {
      const copy = nodes.map((n) => ({ ...n }));
      copy[index] = { ...copy[index], deletedAt };
      client.writeQuery({
        query: ChatReplies,
        variables: { messageID: message.reply.threadParentMsgId },
        data: { message: { ...existing.message, replies: { ...existing.message!.replies, nodes: copy } } },
      });
    }
  } else if (existing?.message) {
    client.writeQuery({ query: ChatReplies, variables: { messageID: message.id }, data: { message: { ...existing.message, deletedAt } } });
  }
}
