// Design tokens. The styled components read them through theme functions, and
// GlobalStyle also publishes them as CSS custom properties for the plain CSS
// files.
export interface Tokens {
  name: "dark" | "light";
  colors: {
    base: string;
    alt: string;
    alt2: string;
    overlay: string;
    text: string;
    textAlt: string;
    textAlt2: string;
    link: string;
    brand: string;
    brandHover: string;
    border: string;
    hoverBg: string;
    error: string;
    warn: string;
    highlight: string;
    highlightFirst: string;
    gift: string;
  };
  fontSizes: Record<1 | 2 | 3 | 4 | 5 | 6 | 7 | 8, string>;
  radii: { small: string; medium: string; large: string; rounded: string };
  space: (units: number) => string;
  shadow: string;
}

const fontSizes = { 1: "3.6rem", 2: "2.4rem", 3: "2rem", 4: "1.8rem", 5: "1.4rem", 6: "1.3rem", 7: "1.2rem", 8: "1.1rem" } as const;
const radii = { small: "0.2rem", medium: "0.4rem", large: "0.6rem", rounded: "9000px" };
const space = (units: number) => `${units * 0.5}rem`;

