import { Children, cloneElement, isValidElement, type ReactElement, type ReactNode } from "react";
import styled, { css, type DefaultTheme } from "styled-components";

export type Spacing = number | string | { x?: number | string; y?: number | string; top?: number | string; right?: number | string; bottom?: number | string; left?: number | string };
export type Display = "block" | "flex" | "inline" | "inline-block" | "inline-flex" | "none" | "grid" | "hide";
export type Background = "base" | "alt" | "alt-2" | "overlay" | "accent" | "none";

export interface LayoutProps {
  display?: Display;
  flexDirection?: "row" | "column" | "row-reverse" | "column-reverse";
  flexWrap?: "wrap" | "nowrap";
  alignItems?: "center" | "start" | "end" | "stretch" | "baseline";
  alignSelf?: "center" | "start" | "end" | "stretch";
  justifyContent?: "center" | "start" | "end" | "between" | "around";
  flexGrow?: number;
  flexShrink?: number;
  flexBasis?: string;
  padding?: Spacing;
  margin?: Spacing;
  overflow?: "hidden" | "auto" | "scroll" | "visible";
  position?: "relative" | "absolute" | "fixed" | "sticky";
  fullWidth?: boolean;
  fullHeight?: boolean;
  width?: string;
  height?: string;
  maxWidth?: string;
  minWidth?: string;
  background?: Background;
  borderRadius?: "small" | "medium" | "large" | "rounded" | "none";
  borderBottom?: boolean;
  borderTop?: boolean;
  textAlign?: "left" | "center" | "right";
  zIndex?: number;
  attachBottom?: boolean;
  attachTop?: boolean;
  elevation?: boolean;
  ellipsis?: boolean;
}

const LAYOUT_PROPS = new Set<string>([
  "display", "flexDirection", "flexWrap", "alignItems", "alignSelf", "justifyContent", "flexGrow", "flexShrink", "flexBasis",
  "padding", "margin", "overflow", "position", "fullWidth", "fullHeight", "width", "height", "maxWidth", "minWidth", "background",
  "borderRadius", "borderBottom", "borderTop", "textAlign", "zIndex", "attachBottom", "attachTop", "elevation", "ellipsis",
]);

export const shouldForwardLayoutProp = (prop: string) => !LAYOUT_PROPS.has(prop);

const unit = (v: number | string) => (typeof v === "number" ? `${v * 0.5}rem` : v);

function spacing(property: "padding" | "margin", value: Spacing | undefined) {
  if (value === undefined) return "";
  if (typeof value !== "object") return `${property}: ${unit(value)};`;
  let out = "";
  const side = (name: string, v: number | string | undefined) => {
    if (v !== undefined) out += `${property}-${name}: ${unit(v)};`;
  };
  side("top", value.y);
  side("bottom", value.y);
  side("left", value.x);
  side("right", value.x);
  side("top", value.top);
  side("right", value.right);
  side("bottom", value.bottom);
  side("left", value.left);
  return out;
}

const justify = { between: "space-between", around: "space-around", start: "flex-start", end: "flex-end", center: "center" } as const;
const align = { start: "flex-start", end: "flex-end", center: "center", stretch: "stretch", baseline: "baseline" } as const;

const backgroundColor = (theme: DefaultTheme, bg: Background) =>
  bg === "base" ? theme.colors.base : bg === "alt" ? theme.colors.alt : bg === "alt-2" ? theme.colors.alt2 : bg === "overlay" ? theme.colors.overlay : bg === "accent" ? theme.colors.brand : "transparent";

type LayoutRule = (props: LayoutProps & { theme: DefaultTheme }, value: never) => string;

const declaration = (name: string) => (_: unknown, value: string | number) => `${name}: ${value};`;

const LAYOUT_RULES: Record<string, LayoutRule> = {
  display: (_, v: string) => (v === "hide" ? "display: none;" : `display: ${v};`),
  flexDirection: declaration("flex-direction"),
  flexWrap: declaration("flex-wrap"),
  alignItems: (_, v: keyof typeof align) => `align-items: ${align[v]};`,
  alignSelf: (_, v: keyof typeof align) => `align-self: ${align[v]};`,
  justifyContent: (_, v: keyof typeof justify) => `justify-content: ${justify[v]};`,
  flexGrow: declaration("flex-grow"),
  flexShrink: declaration("flex-shrink"),
  flexBasis: declaration("flex-basis"),
  padding: (_, v: Spacing) => spacing("padding", v),
  margin: (_, v: Spacing) => spacing("margin", v),
  overflow: declaration("overflow"),
  position: declaration("position"),
  fullWidth: (p, v: boolean) => (v && !p.width ? "width: 100%;" : ""),
  fullHeight: (p, v: boolean) => (v && !p.height ? "height: 100%;" : ""),
  width: declaration("width"),
  height: declaration("height"),
  maxWidth: declaration("max-width"),
  minWidth: declaration("min-width"),
  background: (p, v: Background) => `background-color: ${backgroundColor(p.theme, v)};`,
  borderRadius: (p, v: NonNullable<LayoutProps["borderRadius"]>) => `border-radius: ${v === "none" ? 0 : p.theme.radii[v]};`,
  borderBottom: (p, v: boolean) => (v ? `border-bottom: 1px solid ${p.theme.colors.border};` : ""),
  borderTop: (p, v: boolean) => (v ? `border-top: 1px solid ${p.theme.colors.border};` : ""),
  textAlign: declaration("text-align"),
  zIndex: declaration("z-index"),
  attachBottom: (_, v: boolean) => (v ? "bottom: 0; left: 0; right: 0;" : ""),
  attachTop: (_, v: boolean) => (v ? "top: 0; left: 0; right: 0;" : ""),
  elevation: (p, v: boolean) => (v ? `box-shadow: ${p.theme.shadow};` : ""),
  ellipsis: (_, v: boolean) => (v ? "overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" : ""),
};

/** One interpolation for all style props: it walks the props that are set and looks up a rule for each, as Twitch's Layout does. */
function layoutCss(props: LayoutProps & { theme: DefaultTheme }): string {
  let out = "";
  for (const name in props) {
    const rule = LAYOUT_RULES[name];
    if (rule === undefined) continue;
    const value = props[name as keyof LayoutProps];
    if (value !== undefined && value !== false && value !== "") out += rule(props, value as never);
  }
  return out;
}

export const layoutStyles = css<LayoutProps>`
  ${layoutCss}
`;

export const Layout = styled.div.withConfig({ shouldForwardProp: shouldForwardLayoutProp })<LayoutProps>`
  ${layoutStyles}
`;

const InjectedLayout = styled(({ children, className, ...rest }: { children: ReactElement<{ className?: string }>; className?: string }) =>
  cloneElement(children, { ...rest, className: [children.props.className, className].filter(Boolean).join(" ") }),
).withConfig({ shouldForwardProp: (prop) => prop !== "theme" && shouldForwardLayoutProp(prop) })<LayoutProps>`
  ${layoutStyles}
`;

/** Applies layout style props to its only child by cloning it with a styled class. */
export function InjectLayout({ children, ...props }: LayoutProps & { children: ReactNode }) {
  const child = Children.only(children);
  if (!isValidElement(child)) return <>{child}</>;
  return <InjectedLayout {...props}>{child as ReactElement<{ className?: string }>}</InjectedLayout>;
}
