import { memo, useEffect, useReducer } from "react";
import { Link } from "react-router-dom";
import { useQuery } from "@apollo/client";
import { REALTIME_STREAM_TAG_LIST, STREAM_METADATA, SUBSCRIBE_BUTTON, USE_LIVE, USE_VIEW_COUNT } from "../apollo/documents";
import { setInterval, clearInterval } from "../platform/timers";
import { uptime } from "../shell/format";
import { ICONS, type IconName } from "../shell/icons";
import { t } from "../shell/i18n";
import { Avatar, ButtonIcon, CoreText, IconButton, InjectLayout, Layout, ScCoreButton, SvgIcon, TextBlock, Tooltip } from "../shell/primitives";
import { AboutPanel } from "./AboutPanel";

function Uptime({ login }: { login: string }) {
  const { data } = useQuery(USE_LIVE, { variables: { channelLogin: login } });
  const [, tick] = useReducer((n: number) => n + 1, 0);
  useEffect(() => {
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);
  const createdAt = data?.user?.stream?.createdAt as string | undefined;
  return (
    <Tooltip label="Stream Uptime">
      <Layout className="live-time" as="span" data-a-target="animated-channel-viewers-uptime">
        <CoreText as="span" fontSize={4} color="text-base">
          {createdAt ? uptime(createdAt) : ""}
        </CoreText>
      </Layout>
    </Tooltip>
  );
}

function ViewerCount({ login }: { login: string }) {
  const { data } = useQuery(USE_VIEW_COUNT, { variables: { channelLogin: login } });
  const count = data?.user?.stream?.viewersCount as number | undefined;
  return (
    <Layout className="channel-viewers" display="flex" alignItems="center" color="live" data-a-target="animated-channel-viewers-count">
      <SvgIcon path={ICONS.person} size={16} />
      <Layout margin={{ left: 0.5 }}>
        <CoreText as="span" fontSize={5} bold color="live">
          {count === undefined ? "" : count.toLocaleString("en-US")}
        </CoreText>
      </Layout>
    </Layout>
  );
}

function Tags({ login }: { login: string }) {
  const { data } = useQuery(REALTIME_STREAM_TAG_LIST, { variables: { channelLogin: login } });
  const tags = (data?.user?.stream?.freeformTags ?? []) as { id: string; name: string }[];
  return (
    <Layout className="tag-list" display="flex" flexWrap="wrap" alignItems="center" gap={0.5} data-a-target="channel-tags">
      {tags.map((tag) => (
        <Layout key={tag.id} className="tag-wrapper">
          <Link className="channel-tag tw-link-plain" to={`/directory/all/tags/${tag.name}`} aria-label={`Tag ${tag.name}`}>
            <Layout padding={{ x: 0.5 }}>
              <TextBlock fontSize={3} bold>
                {tag.name}
              </TextBlock>
            </Layout>
          </Link>
        </Layout>
      ))}
    </Layout>
  );
}

function ActionButton({ icon, label, appearance = "secondary", chevron, target }: { icon: IconName; label: string; appearance?: "primary" | "secondary"; chevron?: boolean; target: string }) {
  return (
    <Layout display="flex" alignItems="center" margin={{ right: 0.5 }}>
      <ScCoreButton appearance={appearance} data-a-target={target}>
        <Layout display="flex" alignItems="center" padding={{ x: 0.5 }}>
          <SvgIcon path={ICONS[icon]} size={20} />
          <Layout margin={{ left: 0.5 }} as="span">
            {label}
          </Layout>
        </Layout>
      </ScCoreButton>
      {chevron ? (
        <InjectLayout margin={{ left: 0.2 }}>
          <ScCoreButton appearance="secondary" icon aria-label={`${label} options`}>
            <SvgIcon path={ICONS.chevronDown} size={16} />
          </ScCoreButton>
        </InjectLayout>
      ) : null}
    </Layout>
  );
}

function SubscribeButtons({ login }: { login: string }) {
  const { data } = useQuery(SUBSCRIBE_BUTTON, { variables: { login, includeExpiredDunning: false } });
  const products = (data?.user?.subscriptionProducts ?? []) as unknown[];
  return (
    <Layout display="flex" alignItems="center" data-a-target="subscribe-buttons" data-product-count={products.length}>
      <ActionButton icon="gift" label={t("channel.gift")} chevron target="gift-button" />
      <ActionButton icon="star" label={t("channel.subscribe")} chevron target="subscribe-button" />
    </Layout>
  );
}

export const ChannelInfo = memo(function ChannelInfo({ login }: { login: string }) {
  const { data } = useQuery(STREAM_METADATA, { variables: { channelLogin: login } });
  const user = data?.user;
  const stream = user?.stream;
  return (
    <Layout className="channel-info-content" data-a-target="stream-info-card-component" as="section">
      <Layout className="channel-info-content__header" display="flex" alignItems="flex-start">
        <Layout className="channel-info-content__avatar" position="relative" flexShrink={0}>
          <Layout borderRadius="full" border="2px solid var(--color-fill-live)" padding={0.2}>
            <Avatar src={user?.profileImageURL ?? `data/assets/avatars/${login}/70.png`} size={64} alt={user?.displayName ?? login} />
          </Layout>
          <Layout position="absolute" className="live-tag" as="span" style={{ left: 14, bottom: -6 }}>
            {t("channel.live")}
          </Layout>
        </Layout>
        <Layout flexGrow={1} minWidth="0" display="flex" flexDirection="column" gap={0.5}>
          <Layout display="flex" alignItems="center" justifyContent="space-between">
            <Layout display="flex" alignItems="center">
              <CoreText as="h1" fontSize={7} bold data-a-target="channel-header-displayname">
                {user?.displayName ?? login}
              </CoreText>
              <Layout margin={{ left: 0.5 }} color="text-link" display="flex">
                <Tooltip label="Verified">
                  <Layout display="flex">
                    <SvgIcon path={ICONS.verified} size={16} />
                  </Layout>
                </Tooltip>
              </Layout>
            </Layout>
            <Layout display="flex" alignItems="center">
              <ActionButton icon="heart" label={t("channel.follow")} appearance="primary" target="follow-button" />
              <IconButton path={ICONS.bell} label="Notifications" appearance="secondary" />
              <SubscribeButtons login={login} />
            </Layout>
          </Layout>
          <Layout display="flex" alignItems="flex-start" justifyContent="space-between">
            <Layout flexGrow={1} minWidth="0">
              <CoreText as="h2" fontSize={4} bold lines={2} data-a-target="stream-title">
                {user?.lastBroadcast?.title ?? ""}
              </CoreText>
              <Layout display="flex" alignItems="center" flexWrap="wrap" gap={1} margin={{ top: 0.5 }}>
                {stream?.game ? (
                  <Link className="tw-link" to={`/directory/category/${stream.game.slug}`} data-a-target="stream-game-link">
                    <CoreText as="span" fontSize={4} bold color="text-link">
                      {stream.game.name}
                    </CoreText>
                  </Link>
                ) : null}
                <Tags login={login} />
              </Layout>
            </Layout>
            <Layout display="flex" flexDirection="column" alignItems="flex-end" gap={1}>
              <Layout display="flex" alignItems="center" gap={1}>
                <ViewerCount login={login} />
                <Uptime login={login} />
              </Layout>
              <Layout display="flex" alignItems="center">
                <IconButton path={ICONS.share} label="Share" />
                <IconButton path={ICONS.menu} label="More" />
              </Layout>
            </Layout>
          </Layout>
        </Layout>
      </Layout>
      <AboutPanel login={login} />
    </Layout>
  );
});
