// The interface between the chat pipeline (IRC connection, message buffer)
// and the chat UI. The UI's chat room component owns the buffer, as Twitch's
// owns its MessageBuffer, and reads the visible window through this API.
import type { ChatEvent } from "./types";

export enum PauseReason {
  Scroll = "scroll",
  Mouseover = "mouseover",
  AltKey = "altkey",
}

export interface MessageBufferAPI {
  /** The visible window: at most 150 events, oldest first. Returns a new array. */
  getMessages(): ChatEvent[];
  /** Called after each flush that changed the visible window or the unread count. */
  subscribe(listener: () => void): () => void;
  pause(reason: PauseReason): void;
  unpause(): void;
  isPaused(): boolean;
  pauseReason(): PauseReason | null;
  /** Messages buffered behind the visible window while paused. */
  unreadCount(): number;
  /** Moves the window 40 messages towards the newest. */
  loadNewer(): void;
  /** Jumps to the newest 150 messages and unpauses. */
  loadNewest(): void;
  /** Messages per second, measured each second. */
  chatRate(): number;
  /** Stops the flush and measurement intervals. */
  dispose(): void;
}

export interface ChatConnectionAPI {
  /** Connects (if needed) and joins `login`; events for that channel go to `onEvent`. */
  join(login: string, onEvent: (event: ChatEvent) => void): void;
  part(login: string): void;
  isConnected(): boolean;
}
